module debounce #(
    parameter STABLE_CYCLES = 20
) (
    input wire clk,
    input wire button_in,
    output reg button_out
);

reg [STABLE_CYCLES-1:0] shift_reg = 0;
reg [$clog2(STABLE_CYCLES):0] stable_counter = 0;

always @(posedge clk) begin
    shift_reg <= {shift_reg[STABLE_CYCLES-2:0], button_in};

    if (shift_reg == {STABLE_CYCLES{button_in}}) begin
        if (stable_counter < STABLE_CYCLES) begin
            stable_counter <= stable_counter + 1;
        end
    end else begin
        stable_counter <= 0;
    end

    if (stable_counter == STABLE_CYCLES) begin
        button_out <= button_in;
    end
end

endmodule

