            sel = 4'b01_11;
         else if(inst1412==5 && inst30==0)
            sel = 4'b10_00;
        else if(inst1412==5 && inst30==1)
            sel = 4'b10_10;
        else if(inst1412==6)
            sel = 4'b01_00;
        else if(inst1412==7)
            sel = 4'b01_01;
        end
         endcase
        end
endmodule

