module sync_counter_with_tc(
    input clk,
    input rst,
    input en,
    output reg [11:0] count,
    output reg tc
);

always @(posedge clk)
begin
  if (rst)
    count <= 0;
  else if (en)
    count <= count + 1;

  if (count == 12'b111111111111)
    tc <= 1;
  else
    tc <= 0;
end

