  parameter S1 = 2'b01; // State for detecting first "1"
  parameter S2 = 2'b10; // State for detecting "0"
  parameter S3 = 2'b11; // State for detecting second "1"

  reg [1:0] state;
  reg [1:0] next_state;

  always @ (posedge clk or posedge reset) begin
    if (reset) begin
      state <= S0;
      match <= 1'b0;
    end else begin
      state <= next_state;
      match <= (state == S3); // Output match signal when in S3 state
    end
  end

  always @ (*) begin
    case (state)
      S0: begin
        if (data[15:0] == 4'b1010)
          next_state = S3;
        else if (data[0] == 1'b1)
          next_state = S1;
        else
          next_state = S0;
      end
      S1: begin
        if (data[0] == 1'b0)
          next_state = S2;
        else if (data[15:1] == 14'b0)
          next_state = S0;
        else
          next_state = S1;
      end
      S2: begin
        if (data[0] == 1'b1)
          next_state = S1;
        else if (data[15:2] == 13'b0)
          next_state = S0;
        else
          next_state = S2;
      end
      S3: begin
        next_state = S0;
      end
    endcase
  end

endmodule

